/** Queue one of ART.sprites at (x, y), above the background; opts as for spr (fx, fy ...). */
function sprite(s, x, y, opts = {}) { spr(s.tile, x, y, { size: s.size, pal: s.pal, prio: 3, ...opts }); }

// --- Sound (SPEC 5). Any channel plays any instrument. Songs use channels 0 to 5; effects take turns on 6 and 7, ---
// so they never cut into the music and two can sound at once.

const SFX = { move: 0, select: 1, pause: 2, hit: 3, over: 4, point: 5, record: 6 };
const SONG = { title: 0, play: 1 };
const SFX_CH = [7, 6];
let fxNext = 0;
function fx(n) { sfx(n, SFX_CH[fxNext]); fxNext ^= 1; }

// A song is only started if it is not already playing.
let playing = -1;
function play(song) {
  if (song === playing) return;
  playing = song; music(song);
}

// --- Save slots (SPEC 13) ---

const VERSION_SLOT = 0, SAVE_VERSION = 1, INITIALS_SLOT = 1;
const CHOICE_SLOT = 2, BANK_SLOT = 3, SEEN_SLOT = 40, SEEN_SLOTS = 20;
const RUN_SLOT = 60;   // the run in progress (spec 13): 60 a flag, 61 the seed, 62 the run's numbers, 63 the score, 64 the tallies,
                       // 65 to 69 the doors (2 bits each), 70 and 71 the rooms seen, 72 and 73 the rooms whose item is still there   // the bank's size when the seen bits were kept; the questions asked in earlier runs (640 bits)
const TOP_SLOT = 10, TOP_N = 10, ENTRY = 3; // the top 10, best first: score, initials, a spare (slots 10 to 39)
const LETTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';

// An entry: its score, its initials, and its level and subject (level | (subject + 1) << 4).
function readEntry(i) { const s = TOP_SLOT + i * ENTRY, v = dget(s + 2); return { score: dget(s), initials: unpackInitials(dget(s + 1)), level: v & 15, subject: (v >> 4) - 1 }; }
function writeEntry(i, e) { const s = TOP_SLOT + i * ENTRY; dset(s, e.score); dset(s + 1, packInitials(e.initials)); dset(s + 2, (e.level || 0) | ((e.subject ?? -1) + 1) << 4); }
const topTen = () => Array.from({ length: TOP_N }, (_, i) => readEntry(i));

/** Put a score into the top 10 if it makes it. Returns its row, or -1. */
function insertTop(e) {
  if (!e.score) return -1;
  const list = topTen(), at = list.findIndex((x) => e.score > x.score);
  if (at < 0) return -1;
  list.splice(at, 0, e);
  for (let i = at; i < TOP_N; i++) writeEntry(i, list[i]);
  return at;
}
/** Three characters, 8 bits each. */
const packInitials = (str) => (str.charCodeAt(0) << 16) | (str.charCodeAt(1) << 8) | str.charCodeAt(2);
const unpackInitials = (v) => (v ? String.fromCharCode((v >> 16) & 255, (v >> 8) & 255, v & 255) : '---');
const lastInitials = () => (dget(INITIALS_SLOT) ? unpackInitials(dget(INITIALS_SLOT)) : 'AAA');

// --- Input: edge-triggered presses (btnp repeats; menus want one press) ---

let inputMask = 0, prevMask = 0;
const BUTTONS = [UP, DOWN, LEFT, RIGHT, A, B, X, Y, L, R, START, SELECT];
function readPad() { let m = 0; for (const b of BUTTONS) if (btn(b)) m |= 1 << b; return m; }
const pressed = (b) => (inputMask & (1 << b)) !== 0 && (prevMask & (1 << b)) === 0;

// ===================================================================================================================
// The question bank (spec 6): read from ROM once.
// ===================================================================================================================

const SUBJECTS = ['HISTORY', 'GEOGRAPHY', 'SCIENCE', 'NATURE', 'ARTS AND BOOKS', 'MUSIC AND SCREEN', 'SPORT AND GAMES', 'FOOD AND EVERYDAY'];
const Q_LINE = 30, Q_LINES = 3;   // a question is shown in up to 3 lines of 30 characters
let QUESTIONS = [];
/** The questions from rom('questions') (questions.py writes the format): [{ subj, diff, q, ans: [right, wrong x 3] }]. */
function loadQuestions() {
  const b = rom('questions'), out = [];
  let i = 5;
  const str = () => { const n = b[i++]; let s = ''; for (let k = 0; k < n; k++) s += String.fromCharCode(b[i++]); return s; };
  for (let k = 0, n = b[3] | (b[4] << 8); k < n; k++) {
    const subj = b[i++], diff = b[i++], q = str();
    out.push({ subj, diff, q, ans: [str(), str(), str(), str()] });
  }
  return out;
}
/** Words into lines of at most `w` characters. */
function wrap(s, w) {
  const lines = [];
  let line = '';
  for (const word of s.split(' ')) {
    if (line && line.length + 1 + word.length > w) { lines.push(line); line = word; } else line = line ? `${line} ${word}` : word;
  }
  if (line) lines.push(line);
  return lines;
}

// ===================================================================================================================
// The manor (spec 5): rooms on a grid, a door (or a wall) between each two neighbours.
// ===================================================================================================================

const N = 0, E = 1, S = 2, W = 3, DX = [0, 1, 0, -1], DY = [-1, 0, 1, 0];
const NONE = 0, CLOSED = 1, OPEN = 2, LOCKED = 3;   // a door's state (NONE: a wall)
const MW = 7, MH = 6;   // the manor's size in rooms
let doorsH = [], doorsV = [];   // doorsH[y * (MW - 1) + x]: between (x, y) and (x + 1, y); doorsV[y * MW + x]: (x, y) and (x, y + 1)
const start = { x: 0, y: MH - 1 }, goal = { x: MW - 1, y: 0 };   // the Entrance Hall, bottom left; the heart, top right
let me = { x: 0, y: 0, f: N };   // where you are and which way you face
let seen = new Set();   // the rooms you have seen (on the map)

/** The door from room (x, y) towards d: { list, i } in doorsH or doorsV, or null at the manor's edge. */
function doorRef(x, y, d) {
  const nx = x + DX[d], ny = y + DY[d];
  if (nx < 0 || ny < 0 || nx >= MW || ny >= MH) return null;
  if (d === E || d === W) return { list: doorsH, i: y * (MW - 1) + Math.min(x, nx) };
  return { list: doorsV, i: Math.min(y, ny) * MW + x };
}
function getDoor(x, y, d) { const r = doorRef(x, y, d); return r ? r.list[r.i] : NONE; }
function setDoor(x, y, d, v) { const r = doorRef(x, y, d); if (r) r.list[r.i] = v; }
const roomId = (x, y) => y * MW + x;

// The rooms' kinds (spec 6): a name, and the ghost who asks there. The first is the start's, the last the heart's.
const KINDS = [
  ['ENTRANCE HALL', 'THE BUTLER'], ['LIBRARY', 'THE LIBRARIAN'], ['GALLERY', 'THE PAINTER'], ['DINING ROOM', 'THE DUCHESS'],
  ['KITCHEN', 'THE COOK'], ['CONSERVATORY', 'THE GARDENER'], ['MUSIC ROOM', 'THE ORGANIST'], ['NURSERY', 'THE TWINS'],
  ['ARMOURY', 'THE KNIGHT'], ['CLOCK ROOM', 'LADY RIDDLEWICK'],
];
const HALL = 0, HEART = KINDS.length - 1;
const EXTRA_DOORS = 0.3, N_KEYS = 3, N_STUBS = 2;   // the share of the maze's remaining walls that get a door; what lies about
const ITEM_NONE = 0, ITEM_KEY = 1, ITEM_STUB = 2;
let kinds = [], items = [];   // by room: its kind (an index into KINDS), and what lies in it

/** A small seeded random number generator (mulberry32), so a run's manor can be made again from its seed (the save). */
function seeded(seed) {
  let a = seed >>> 0;
  return (n) => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return Math.floor((((t ^ (t >>> 14)) >>> 0) / 4294967296) * n);
  };
}

/** The manor of a seed (spec 5): a maze (a random spanning tree, so every room can be reached), a door in about 30% of
 * its other walls (loops, other ways round), the rooms' kinds (no two neighbours alike where possible), and the keys and
 * candle stubs, away from the start. */
function makeManor(seed) {
  const r = seeded(seed);
  doorsH = new Array((MW - 1) * MH).fill(NONE); doorsV = new Array(MW * (MH - 1)).fill(NONE);
  const inTree = new Set([roomId(start.x, start.y)]), frontier = [];
  const addEdges = (x, y) => { for (let d = 0; d < 4; d++) if (doorRef(x, y, d)) frontier.push([x, y, d]); };
  addEdges(start.x, start.y);
  while (frontier.length) {   // Prim's maze: a random edge from the tree to a room not yet in it
    const [x, y, d] = frontier.splice(r(frontier.length), 1)[0], nx = x + DX[d], ny = y + DY[d];
    if (inTree.has(roomId(nx, ny))) continue;
    setDoor(x, y, d, CLOSED); inTree.add(roomId(nx, ny)); addEdges(nx, ny);
  }
  for (const list of [doorsH, doorsV]) for (let i = 0; i < list.length; i++) if (list[i] === NONE && r(100) < EXTRA_DOORS * 100) list[i] = CLOSED;
  kinds = [];
  for (let y = 0; y < MH; y++) for (let x = 0; x < MW; x++) {
    let k, tries = 0;
    do k = 1 + r(HEART - 1); while (tries++ < 12 && ((x > 0 && kinds[roomId(x - 1, y)] === k) || (y > 0 && kinds[roomId(x, y - 1)] === k)));
    kinds.push(k);
  }
  kinds[roomId(start.x, start.y)] = HALL; kinds[roomId(goal.x, goal.y)] = HEART;
  items = new Array(MW * MH).fill(ITEM_NONE);
  const spots = [];
  for (let y = 0; y < MH; y++) for (let x = 0; x < MW; x++) if (Math.abs(x - start.x) + Math.abs(y - start.y) >= 2 && !(x === goal.x && y === goal.y)) spots.push(roomId(x, y));
  for (let i = 0; i < N_KEYS + N_STUBS; i++) items[spots.splice(r(spots.length), 1)[0]] = i < N_KEYS ? ITEM_KEY : ITEM_STUB;
}

/** Can the heart still be reached from (x, y) through doors that are closed or open (not locked)? */
function canReach(x, y) {
  const todo = [[x, y]], been = new Set([roomId(x, y)]);
  while (todo.length) {
    const [cx, cy] = todo.pop();
    if (cx === goal.x && cy === goal.y) return true;
    for (let d = 0; d < 4; d++) {
      const st = getDoor(cx, cy, d), nx = cx + DX[d], ny = cy + DY[d];
      if ((st === CLOSED || st === OPEN) && !been.has(roomId(nx, ny))) { been.add(roomId(nx, ny)); todo.push([nx, ny]); }
    }
  }
  return false;
}

// ===================================================================================================================
// A run (spec 5, 9).
// ===================================================================================================================

// The levels (spec 5): the candle's notches, and the questions' difficulty (and the points) are the level's number.
const LEVELS = [{ name: 'NOVICE', candle: 6 }, { name: 'SCHOLAR', candle: 5 }, { name: 'SAGE', candle: 4 }, { name: 'MASTER', candle: 3 }];
let level = 1;   // 1 to 4 (step 4 adds the choice of level and subject)
let subject = -1;   // an index into SUBJECTS, or -1 for ALL SUBJECTS
let skipTitle = false; // tests set this to land straight in the game
let state = 'title', paused = false, timer = 0, clock = 0;
let titleSel = 0, pauseSel = 0, rank = -1, hl = -1, initials = null;
let score = 0, streak = 0, asked = new Set(), answered = 0, rightCount = 0, won = false;
let runSeed = 0, candle = 6, keys = 0, notice = '', noticeT = 0;
let phase = 'explore', sel = 0, cur = null, walkT = 0, walkTo = null;   // sel: the door chosen, as a direction (N, E, S, W)

function init() {
  if (dget(VERSION_SLOT) !== SAVE_VERSION) { // a new or older save: start clean
    for (let i = 0; i < 256; i++) dset(i, 0);
    dset(VERSION_SLOT, SAVE_VERSION);
  }
  QUESTIONS = loadQuestions();
  if (dget(BANK_SLOT) !== QUESTIONS.length) {   // the bank has changed: what was asked before no longer lines up
    for (let k = 0; k < SEEN_SLOTS; k++) dset(SEEN_SLOT + k, 0);
    dset(BANK_SLOT, QUESTIONS.length);
  }
  ROOMS = rom('rooms');
  // The layers (spec 12): BG2 the room and the panel (or the title), BG1 the furniture, BG0 the doors; the overlay's glass
  // and the ghost (sprite palette 5) are see-through.
  bg(2, { mx: 0, my: 0, mw: 32, mh: 28, x: 0, y: 0, wrap: false, show: true });
  bg(1, { mx: FUR_MX, my: 0, mw: 32, mh: 17, x: 0, y: 0, wrap: false, show: true });
  bg(0, { mx: DOOR_MX, my: 0, mw: 32, mh: 17, x: 0, y: 0, wrap: false, show: true });
  blend({ layers: ['overlay', 'spr'], half: true });
  if (skipTitle) startGame(); else toTitle();
}

function toTitle() { state = 'title'; timer = 0; titleSel = 0; paused = false; play(SONG.title); }

function startGame() {
  runSeed = rndi(1, 0x3fffffff); makeManor(runSeed);
  me = { x: start.x, y: start.y, f: N }; seen = new Set([roomId(me.x, me.y)]);
  candle = LEVELS[level - 1].candle; keys = 0; notice = ''; noticeT = 0;
  score = 0; streak = 0; asked = new Set(); answered = 0; rightCount = 0; won = false;
  phase = 'explore'; cur = null; sel = firstDoor(); paused = false; timer = 0; state = 'play';
  play(SONG.play);
}

/** The door to choose first in a room: ahead if there is one, then right, left, behind. */
function firstDoor() {
  for (const k of [0, 1, 3, 2]) { const d = (me.f + k) % 4; if (getDoor(me.x, me.y, d) !== NONE) return d; }
  return me.f;
}

/** Has question i been asked in an earlier run (or this one)? The bits are kept in the save (slots 40 to 59). */
const seenBefore = (i) => (dget(SEEN_SLOT + (i >> 5)) >>> (i & 31)) & 1;
function markSeen(i, on) { const k = SEEN_SLOT + (i >> 5), b = 1 << (i & 31); dset(k, on ? dget(k) | b : dget(k) & ~b); }

/** A question for the door (spec 6): of the run's subject (any, for ALL SUBJECTS) at the level's difficulty, not asked
 * yet in this run, and not asked in an earlier run where possible. When a difficulty runs dry, the nearest fills in. */
function pickQuestion() {
  const fits = (i) => subject < 0 || QUESTIONS[i].subj === subject;
  let qi = -1;
  for (let off = 0; off < 4 && qi < 0; off++) for (const dd of off ? [level - off, level + off] : [level]) {   // the level's difficulty, then the nearest
    if (dd < 1 || dd > 4 || qi >= 0) continue;
    const pool = QUESTIONS.map((_, i) => i).filter((i) => fits(i) && QUESTIONS[i].diff === dd && !asked.has(i));
    if (!pool.length) continue;
    let fresh = pool.filter((i) => !seenBefore(i));
    if (!fresh.length) { pool.forEach((i) => markSeen(i, false)); fresh = pool; }   // all asked in earlier runs: that pool starts afresh
    qi = fresh[rndi(0, fresh.length - 1)];
  }
  if (qi < 0) { asked.clear(); return pickQuestion(); }   // every question of the subject asked in this run: start again
  asked.add(qi); markSeen(qi, true);
  const order = [0, 1, 2, 3];
  for (let i = 3; i > 0; i--) { const j = rndi(0, i); [order[i], order[j]] = [order[j], order[i]]; }
  return { qi, order, sel: 0, door: sel, chosen: -1, right: false };
}

const pointsFor = () => 100 * level + 25 * level * Math.min(streak, 4);
const winBonus = () => 1000 * level + 200 * level * candle;
function say(s) { notice = s; noticeT = 150; }
/** After a door locks or a key is used: if no way to the heart is left and you carry no key, a ghost gives you one. */
function checkStuck() {
  if (keys === 0 && !canReach(me.x, me.y)) { keys = 1; say(`${KINDS[kinds[roomId(me.x, me.y)]][1]} SLIPS YOU A KEY`); fx(SFX.point); }
}

// --- Update ---

function update() {
  inputMask = readPad(); clock++;
  if (!paused) timer++; // a state's clock: it stands still while paused
  if (paused) updatePause();
  else if (state === 'title') updateTitle();
  else if (state === 'play') updatePlay();
  else if (state === 'over') updateOver();
  else if (state === 'initials') updateInitials();
  else if (state === 'records') updateRecords();
  else if (state === 'setup') updateSetup();
  prevMask = inputMask;
}

// --- The title and the new game's choices (spec 10) ---

const titleItems = () => (hasRun() ? ['CONTINUE', 'NEW GAME', 'RECORDS'] : ['NEW GAME', 'RECORDS']);
function updateTitle() {
  const items = titleItems(), n = items.length;
  if (titleSel >= n) titleSel = 0;
  if (pressed(UP)) { titleSel = (titleSel + n - 1) % n; fx(SFX.move); }
  if (pressed(DOWN)) { titleSel = (titleSel + 1) % n; fx(SFX.move); }
  if (!(pressed(A) || pressed(START)) || timer < 10) return;
  fx(SFX.select);
  const it = items[titleSel];
  if (it === 'CONTINUE') continueRun();
  else if (it === 'NEW GAME') toSetup();
  else { state = 'records'; hl = -1; timer = 0; }
}

let setupRow = 0;
function toSetup() {
  const c = dget(CHOICE_SLOT);   // the last choice (0: none yet)
  if (c) { subject = (c & 15) - 1; level = (c >> 4) & 15 || 1; } else { subject = -1; level = 1; }
  state = 'setup'; setupRow = 0; timer = 0;
}
/** The new game: UP and DOWN choose the row (SUBJECT, LEVEL), LEFT and RIGHT change it, A begins, B goes back. */
function updateSetup() {
  if (pressed(UP) || pressed(DOWN)) { setupRow ^= 1; fx(SFX.move); }
  const d = pressed(RIGHT) ? 1 : pressed(LEFT) ? -1 : 0;
  if (d && setupRow === 0) { subject = ((subject + 1 + d + 9) % 9) - 1; fx(SFX.move); }
  if (d && setupRow === 1) { level = ((level - 1 + d + 4) % 4) + 1; fx(SFX.move); }
  if (pressed(B)) { fx(SFX.pause); toTitle(); return; }
  if (timer > 10 && (pressed(A) || pressed(START))) { fx(SFX.select); dset(CHOICE_SLOT, (subject + 1) | (level << 4)); startGame(); }
}

// --- The run in progress, saved while you explore and made again from it (CONTINUE) ---

const hasRun = () => dget(RUN_SLOT) === 1;
function clearRun() { for (let k = 0; k < 14; k++) dset(RUN_SLOT + k, 0); }
/** 21 flags a slot (so no slot's top bit is used): a set of room numbers 0 to 41 into two slots. */
function packRooms(has, k) { let a = 0, b = 0; for (let r = 0; r < MW * MH; r++) if (has(r)) { if (r < 21) a |= 1 << r; else b |= 1 << (r - 21); } dset(k, a); dset(k + 1, b); }
const roomBit = (k, r) => (r < 21 ? dget(k) >> r : dget(k + 1) >> (r - 21)) & 1;
function saveRun() {
  dset(RUN_SLOT, 1); dset(RUN_SLOT + 1, runSeed);
  dset(RUN_SLOT + 2, (subject + 1) | level << 4 | me.f << 8 | me.x << 12 | me.y << 16 | Math.min(candle, 15) << 20 | Math.min(keys, 15) << 24);
  dset(RUN_SLOT + 3, score);
  dset(RUN_SLOT + 4, Math.min(streak, 255) | Math.min(answered, 255) << 8 | Math.min(rightCount, 255) << 16);
  const doors = [...doorsH, ...doorsV];
  for (let k = 0; k < 5; k++) { let v = 0; for (let j = 0; j < 15; j++) v |= (doors[k * 15 + j] || 0) << (j * 2); dset(RUN_SLOT + 5 + k, v); }
  packRooms((r) => seen.has(r), RUN_SLOT + 10);
  packRooms((r) => items[r] !== ITEM_NONE, RUN_SLOT + 12);
}
/** CONTINUE: the manor made again from the seed, then the doors, rooms seen, items taken and the numbers put back. */
function continueRun() {
  runSeed = dget(RUN_SLOT + 1); makeManor(runSeed);
  const v = dget(RUN_SLOT + 2), t = dget(RUN_SLOT + 4);
  subject = (v & 15) - 1; level = (v >> 4) & 15; me = { f: (v >> 8) & 15, x: (v >> 12) & 15, y: (v >> 16) & 15 };
  candle = (v >> 20) & 15; keys = (v >> 24) & 15; score = dget(RUN_SLOT + 3);
  streak = t & 255; answered = (t >> 8) & 255; rightCount = (t >> 16) & 255;
  const nH = doorsH.length;
  for (let i = 0; i < nH + doorsV.length; i++) {
    const d = (dget(RUN_SLOT + 5 + flr(i / 15)) >> ((i % 15) * 2)) & 3;
    if (i < nH) doorsH[i] = d; else doorsV[i - nH] = d;
  }
  seen = new Set();
  for (let r = 0; r < MW * MH; r++) { if (roomBit(RUN_SLOT + 10, r)) seen.add(r); if (!roomBit(RUN_SLOT + 12, r)) items[r] = ITEM_NONE; }
  asked = new Set(); won = false; notice = ''; noticeT = 0; cur = null; paused = false; timer = 0; state = 'play'; phase = 'explore';
  sel = firstDoor(); play(SONG.play);
  if (me.x === goal.x && me.y === goal.y) { cur = { ...pickQuestion(), final: true }; phase = 'ask'; }   // back to her last question
}

function updatePlay() {
  if (pressed(START) && phase !== 'walk') { paused = true; pauseSel = 0; fx(SFX.pause); return; }
  if (noticeT) noticeT--;
  if (phase === 'explore') updateExplore();
  else if (phase === 'ask') updateAsk();
  else if (phase === 'confirm') updateConfirm();
  if (state === 'play' && (phase === 'explore' || (phase === 'ask' && cur.final))) saveRun();   // (unchanged slots are not written)
  else if (phase === 'answered') updateAnswered();
  else if (phase === 'walk') updateWalk();
}

/** Exploring: the d-pad chooses a door (UP ahead, RIGHT, DOWN behind, LEFT), A knocks or walks through. */
function updateExplore() {
  for (const [b, k] of [[UP, 0], [RIGHT, 1], [DOWN, 2], [LEFT, 3]]) {
    if (!pressed(b)) continue;
    const d = (me.f + k) % 4;
    if (getDoor(me.x, me.y, d) !== NONE) { sel = d; fx(SFX.move); }
  }
  if (!pressed(A)) return;
  const door = getDoor(me.x, me.y, sel);
  if (door === OPEN) walk(sel);
  else if (door === CLOSED) { cur = pickQuestion(); phase = 'ask'; timer = 0; fx(SFX.select); }
  else if (door === LOCKED) {
    if (keys) { phase = 'confirm'; timer = 0; fx(SFX.select); } else { say('LOCKED FOR GOOD'); fx(SFX.hit); }
  }
}

/** A locked door, with a key in your pocket: A uses it, B does not. */
function updateConfirm() {
  if (pressed(B)) { phase = 'explore'; fx(SFX.move); return; }
  if (!pressed(A) || timer < 6) return;
  keys--; setDoor(me.x, me.y, sel, OPEN); checkStuck(); walk(sel);
}

/** A question: UP and DOWN choose an answer, A answers, B uses a key instead (not on the heart's last question). */
function updateAsk() {
  if (pressed(UP)) { cur.sel = (cur.sel + 3) % 4; fx(SFX.move); }
  if (pressed(DOWN)) { cur.sel = (cur.sel + 1) % 4; fx(SFX.move); }
  if (timer < 10) return;
  if (pressed(B) && !cur.final) {
    if (!keys) { say('YOU HAVE NO KEY'); fx(SFX.hit); return; }
    keys--; asked.delete(cur.qi); setDoor(me.x, me.y, cur.door, OPEN); checkStuck();
    const d = cur.door; cur = null; walk(d); return;
  }
  if (!pressed(A)) return;
  cur.chosen = cur.sel; cur.right = cur.order[cur.sel] === 0; answered++;
  if (cur.right) {
    score += pointsFor(); streak++; rightCount++; fx(SFX.point);
    if (cur.final) score += winBonus(); else setDoor(me.x, me.y, cur.door, OPEN);
  } else {
    streak = 0; candle--; fx(SFX.hit);
    if (!cur.final) { setDoor(me.x, me.y, cur.door, LOCKED); if (candle > 0) checkStuck(); }
  }
  phase = 'answered'; timer = 0;
}

/** The answer shown for a moment (the right one lit), then through the door, or back to the room; the run's end. */
function updateAnswered() {
  if (timer < 50 && !(timer > 15 && pressed(A))) return;
  const { door, right, final } = cur;
  cur = null; phase = 'explore';
  if (final && right) { won = true; gameOver(); return; }
  if (candle <= 0) { gameOver(); return; }
  if (final) { cur = { ...pickQuestion(), final: true }; phase = 'ask'; timer = 0; return; }   // the heart asks again
  if (right) walk(door); else sel = firstDoor();
}

function walk(d) { phase = 'walk'; walkT = 0; walkTo = d; fx(SFX.select); }
/** Through the door: the screen dims, you are in the next room facing the way you walked, and it brightens. */
function updateWalk() {
  walkT++;
  if (walkT === 12) {
    me = { x: me.x + DX[walkTo], y: me.y + DY[walkTo], f: walkTo };
    seen.add(roomId(me.x, me.y)); sel = firstDoor();
    pickUp();
  }
  if (walkT >= 24) {
    phase = 'explore'; brightness(15);
    if (me.x === goal.x && me.y === goal.y) {   // the heart: its keeper's last question
      cur = { ...pickQuestion(), final: true }; phase = 'ask'; timer = 0;
      say('LADY RIDDLEWICK HAS ONE LAST QUESTION');
    }
  } else brightness(Math.round(Math.abs(walkT - 12) * 15 / 12));
}

/** What lies in the room you walk into: a key (always taken), a candle stub (taken if the candle is not full). */
function pickUp() {
  const r = roomId(me.x, me.y), it = items[r];
  if (it === ITEM_KEY) { keys++; items[r] = ITEM_NONE; say('YOU FIND A SKELETON KEY'); fx(SFX.point); }
  else if (it === ITEM_STUB) {
    if (candle < LEVELS[level - 1].candle) { candle++; items[r] = ITEM_NONE; say('A CANDLE STUB: YOUR CANDLE GROWS'); fx(SFX.point); }
    else say('A CANDLE STUB (YOUR CANDLE IS FULL)');
  }
}

function gameOver() {
  state = 'over'; timer = 0; play(-1); fx(SFX.over); brightness(15);
  clearRun();
  rank = insertTop({ score, initials: lastInitials(), level, subject });
}

function updateOver() {
  if (timer < 60 || !(pressed(A) || pressed(START))) return;
  fx(SFX.select);
  if (rank >= 0) { state = 'initials'; timer = 0; initials = { chars: lastInitials().split(''), pos: 0 }; fx(SFX.record); }
  else toTitle();
}

/** UP/DOWN pick a letter, LEFT/RIGHT (or A and B) move, START saves (as does A on the last letter). */
function updateInitials() {
  const ini = initials, k = LETTERS.indexOf(ini.chars[ini.pos]);
  if (pressed(UP)) { ini.chars[ini.pos] = LETTERS[(k + 1) % LETTERS.length]; fx(SFX.move); }
  if (pressed(DOWN)) { ini.chars[ini.pos] = LETTERS[(k + LETTERS.length - 1) % LETTERS.length]; fx(SFX.move); }
  if (pressed(LEFT) || pressed(B)) ini.pos = Math.max(0, ini.pos - 1);
  if (pressed(RIGHT)) ini.pos = Math.min(2, ini.pos + 1);
  const done = pressed(START) || (pressed(A) && ini.pos === 2);
  if (pressed(A) && ini.pos < 2) ini.pos++;
  if (!done || timer < 20) return;
  const v = packInitials(ini.chars.join(''));
  dset(INITIALS_SLOT, v); dset(TOP_SLOT + rank * ENTRY + 1, v);
  fx(SFX.select);
  state = 'records'; hl = rank; timer = 0;
}

function updateRecords() {
  if ((pressed(START) || pressed(A) || pressed(B)) && timer > 20) { fx(SFX.select); toTitle(); }
}

const PAUSE_MENU = ['RESUME', 'QUIT TO TITLE'];
function updatePause() {
  if (pressed(UP) || pressed(DOWN)) { pauseSel ^= 1; fx(SFX.move); }
  if (pressed(B) || (pressed(START) && pauseSel === 0)) { paused = false; fx(SFX.pause); }
  else if (pressed(A) || pressed(START)) {
    fx(SFX.select);
    if (pauseSel === 0) paused = false; else toTitle();
  }
}

// --- Draw ---

const VIEW_H = 136;   // the room's view: y 0 to 135; the panel below
const FUR_MX = 64, DOOR_MX = 96;   // where in Map RAM the furniture's (BG1) and the doors' (BG0) cells are written
const DOOR_PAL = [0, 3, 4, 5];     // a door's palette by its state: closed, open (a dark doorway), locked
let ROOMS = null, roomKind = -1;   // each kind's colours (rom/rooms.bin, made by art.py); the kind now loaded
const PARCH = { x: 7, y: 151, c: 10 };   // the map on the panel's parchment: its top left and a room's size

/** Palette 1 (the room's) set to a kind's colours: 15 RGB555 values each. */
function loadRoomColours(k) {
  if (k === roomKind) return;
  roomKind = k;
  for (let i = 1; i < 16; i++) { const o = (k * 15 + i - 1) * 2, v = ROOMS[o] | (ROOMS[o + 1] << 8); color(16 + i, v & 31, (v >> 5) & 31, v >> 10); }
}

/** The room on the layers: its colours, its furniture either side of the back door (BG1), and its doors (BG0). */
function renderRoom() {
  loadRoomColours(kinds[roomId(me.x, me.y)]);
  for (let y = 0; y < 17; y++) for (let x = 0; x < 32; x++) { mset(FUR_MX + x, y, 0); mset(DOOR_MX + x, y, 0); }
  const k = kinds[roomId(me.x, me.y)];
  for (let j = 0; j < 7; j++) for (let i = 0; i < 4; i++) {
    const t = ART.tiles[`fur${k}_${i}_${j}`];
    if (!t) continue;
    mset(FUR_MX + 9 + i, 6 + j, tile(t, 2)); mset(FUR_MX + 22 - i, 6 + j, tile(t, 2, true));   // the right one mirrored
  }
  for (const rel of [0, 1, 3]) {
    const st = getDoor(me.x, me.y, (me.f + rel) % 4);
    if (st === NONE) continue;
    if (rel === 0) {
      for (let j = 0; j < 7; j++) for (let i = 0; i < 4; i++) { const t = ART.tiles[`door_back_${i}_${j}`]; if (t) mset(DOOR_MX + 14 + i, 6 + j, tile(t, DOOR_PAL[st])); }
    } else {
      for (let j = 0; j < 11; j++) for (let i = 0; i < 4; i++) {
        const t = ART.tiles[`door_side_${i}_${j}`];
        if (!t) continue;
        if (rel === 3) mset(DOOR_MX + 2 + i, 5 + j, tile(t, DOOR_PAL[st])); else mset(DOOR_MX + 29 - i, 5 + j, tile(t, DOOR_PAL[st], true));
      }
    }
  }
}

function draw() {
  cls();
  const inManor = state === 'play' || state === 'over';
  bg(2, { mx: inManor ? 0 : ART.scenes.title.mx }); bg(1, { show: inManor }); bg(0, { show: inManor });
  if (inManor) drawPlay();
  else if (state === 'title') drawTitle();
  else if (state === 'initials') drawInitials();
  else if (state === 'records') drawRecords();
  else if (state === 'setup') drawSetup();
  if (state === 'over') drawEnd();
  if (paused) drawPause();
}
/** The night sky behind the title, a colour for each line; elsewhere the backdrop stays dark. */
function scanline(y) { if (state === 'title' || state === 'setup' || state === 'records' || state === 'initials') gradientLine(ART.gradients.night, y); else if (y === 0) color(0, 1, 0, 2); }

function drawPlay() {
  renderRoom();
  drawRoomSprites();
  if (phase === 'ask' || phase === 'answered') drawQuestion(); else drawPanel();
}

// Where a door's things go, by where it is from you (0 ahead, 1 right, 2 behind, 3 left): its arrow, its padlock, its ghost.
const DOOR_SPOTS = [
  { arrow: [120, 30], lock: [120, 66], ghost: [112, 38] },
  { arrow: [217, 24], lock: [218, 74], ghost: [206, 44] },
  { arrow: [120, 118], lock: [120, 118], ghost: [112, 48] },
  { arrow: [23, 24], lock: [22, 74], ghost: [18, 44] },
];
const PROP_DY = [-8, 6, -6, -5, -10, -7, -6, -4, -6, -8];   // each ghost's prop, from the ghost's top (a hat sits above, spectacles on the eyes)
/** The sprites in the room: padlocks on locked doors, the gold arrow over the chosen door, and the ghost who is asking. */
function drawRoomSprites() {
  const S = ART.sprites, bob = Math.round(Math.sin(clock / 9) * 2);
  for (const rel of [0, 1, 3]) {
    if (getDoor(me.x, me.y, (me.f + rel) % 4) !== LOCKED) continue;
    const [x, y] = DOOR_SPOTS[rel].lock; spr(S.padlock.tile, x - 8, y - 8, { size: 16, pal: S.padlock.pal, prio: 3 });
  }
  const back = getDoor(me.x, me.y, (me.f + 2) % 4), choosing = state === 'play' && (phase === 'explore' || phase === 'confirm');
  if (back !== NONE && !(choosing && sel === (me.f + 2) % 4)) {   // the door behind you, when it is not chosen: a dim arrow at the bottom
    const c = back === LOCKED ? RED : DIM;
    for (let i = 0; i < 5; i++) line(128 - 5 + i, 124 + i, 128 + 5 - i, 124 + i, c);
  }
  if (choosing) {
    const rel = (sel - me.f + 4) % 4, [x, y] = DOOR_SPOTS[rel].arrow;
    spr(S.arrow.tile, x - 8, y - 8 + bob, { size: 16, pal: S.arrow.pal, prio: 3 });
  }
  if ((phase === 'ask' || phase === 'answered') && cur) {
    const rel = (cur.door - me.f + 4) % 4, k = cur.final ? HEART : kinds[roomId(me.x, me.y)], f = flr(clock / 20) % 2;
    const [x, y0] = DOOR_SPOTS[rel].ghost, y = y0 + bob;
    spr(S[`ghost_top${f}`].tile, x, y, { size: 32, pal: 5, prio: 3 });
    spr(S[`ghost_bot${f}`].tile, x, y + 32, { size: 32, pal: 5, prio: 3 });
    const P = S[`prop${k}`]; spr(P.tile, x + 8, y + PROP_DY[k], { size: 16, pal: P.pal, prio: 3 });
  }
}

/** The panel while exploring (on the desk): the map on its parchment, the room's name, the score, keys, the candle,
 * notices, and what A does. */
function drawPanel() {
  const C = ART.colors;
  drawMap(PARCH.x, PARCH.y, PARCH.c);
  txt(KINDS[kinds[roomId(me.x, me.y)]][0], 86, VIEW_H + 8, GOLD);
  txt(`SCORE ${score}`, 86, VIEW_H + 22, C.CREAM);
  for (let i = 0; i < keys; i++) spr(ART.sprites.key.tile, 86 + i * 10, VIEW_H + 36, { size: 8, pal: ART.sprites.key.pal, prio: 3 });
  if (noticeT) wrap(notice, 17).slice(0, 3).forEach((l, i) => txt(l, 86, VIEW_H + 48 + i * 10, CYAN));
  drawCandle(232, 214);
  if (state !== 'play') return;
  if (phase === 'confirm') { txt('USE A KEY?', 86, VIEW_H + 66, GOLD); txt('A: YES  B: NO', 86, VIEW_H + 76, GOLD); return; }
  if (phase !== 'explore') return;
  const st = getDoor(me.x, me.y, sel);
  txt(st === OPEN ? 'A: GO THROUGH' : st === LOCKED ? (keys ? 'A: USE A KEY' : 'LOCKED') : 'A: KNOCK', 86, VIEW_H + 76, st === LOCKED && !keys ? RED : GOLD);
}

/** The candle: a brass holder, the wax as tall as the notches left (of the level's full candle), a flickering flame. */
function drawCandle(cx, by) {
  const C = ART.colors, S = ART.sprites, full = LEVELS[level - 1].candle, h = candle * 7;
  spr(S.holder.tile, cx - 8, by - 10, { size: 16, pal: S.holder.pal, prio: 3 });
  rect(cx - 4, by - 4 - full * 7, 8, full * 7, C.FADED);   // where the full candle reached
  if (candle > 0) {
    rectfill(cx - 3, by - 3 - h, 6, h, C.WAX); rectfill(cx + 1, by - 3 - h, 2, h, C.WAXSHADE);
    for (let i = 1; i < candle; i++) pset(cx - 3, by - 3 - i * 7, C.WAXSHADE);   // its notches
    const F = S[`flame${flr(clock / 7) % 2}`]; spr(F.tile, cx - 4, by - 11 - h, { size: 8, pal: F.pal, prio: 3 });
  }
}

/** The map, in ink on the parchment: the rooms you have seen, their doors (open: a gap; locked: a red seal; closed: a
 * line), the heart (gold), and you (a red dot and a tick the way you face). */
function drawMap(x0, y0, c) {
  const C = ART.colors;
  for (let y = 0; y < MH; y++) for (let x = 0; x < MW; x++) {
    const px = x0 + x * c, py = y0 + y * c, isGoal = x === goal.x && y === goal.y;
    if (!seen.has(roomId(x, y)) && !isGoal) continue;
    if (isGoal) rectfill(px + 1, py + 1, c - 2, c - 2, C.GOLD);
    rect(px, py, c, c, isGoal && !seen.has(roomId(x, y)) ? C.FADED : C.INK);
    for (let d = 0; d < 4; d++) {
      const st = getDoor(x, y, d);
      if (st === NONE) continue;
      const mx = px + c / 2 + DX[d] * (c / 2), my = py + c / 2 + DY[d] * (c / 2), horiz = d === N || d === S;
      const col = st === OPEN ? C.CREAM : st === LOCKED ? C.SEAL : C.FADED;
      if (horiz) rectfill(mx - 2, my, 4, 1, col); else rectfill(mx, my - 2, 1, 4, col);
    }
  }
  const mx = x0 + me.x * c + c / 2, my = y0 + me.y * c + c / 2;
  rectfill(mx - 1, my - 1, 3, 3, C.SEAL); line(mx, my, mx + DX[me.f] * 4, my + DY[me.f] * 4, C.SEAL);
}

/** A question: who asks, the question, and the four answers, one lit (the ghost is a sprite, at its door). */
function drawQuestion() {
  const q = QUESTIONS[cur.qi], kind = kinds[roomId(me.x, me.y)];
  panel(0, 112, 256, 112);
  if (phase === 'ask') txt(cur.final ? 'LADY RIDDLEWICK ASKS:' : `${KINDS[kind][1]} ASKS:`, 8, 117, cur.final ? GOLD : CYAN);
  if (phase === 'ask' && keys && !cur.final) txt(`B: KEY (${keys})`, 248 - 8 * (8 + String(keys).length), 117, DIM);
  wrap(q.q, Q_LINE).forEach((l, i) => txt(l, 8, 130 + i * 11, WHITE));
  cur.order.forEach((a, i) => {
    const y = 167 + i * 13, isRight = a === 0;
    let c = i === cur.sel ? GOLD : WHITE;
    if (phase === 'answered') c = isRight ? GREEN : i === cur.chosen ? RED : DIM;
    if (phase === 'ask' && i === cur.sel) rectfill(4, y - 3, 248, 12, PANEL);
    txt(`${'ABCD'[i]}  ${q.ans[a]}`, 12, y, c);
  });
  if (phase === 'answered') {
    const msg = cur.right ? (cur.final ? 'RIGHT! THE MANOR IS YOURS' : 'RIGHT! THE DOOR OPENS') : candle <= 0 ? 'WRONG! YOUR CANDLE GOES OUT' : cur.final ? 'WRONG! YOUR CANDLE BURNS' : 'WRONG! THE DOOR LOCKS';
    txt(msg, 8, 117, cur.right ? GREEN : RED);
  }
}

function drawEnd() {
  panel(24, 72, 208, 72);
  ctxt(won ? 'YOU FOUND THE HEART' : 'YOUR CANDLE HAS GONE OUT', 80, won ? GOLD : RED);
  ctxt(`SCORE ${score}`, 98, WHITE);
  ctxt(`${rightCount} OF ${answered} ANSWERED RIGHT`, 112, DIM);
  if (timer > 60 && timer % 60 < 40) ctxt('START: CONTINUE', 128, DIM);
}

/** The title: the manor at night (BG2) with the name; the menu in a glass panel below it, and a saved run's line. */
function drawTitle() {
  const items = titleItems(), h = items.length * 11 + (hasRun() ? 14 : 4);
  panel(56, 222 - h - 4, 144, h + 4, true);
  items.forEach((s, i) => txt(`${i === titleSel ? '> ' : '  '}${s}`, 72, 222 - h + i * 11, i === titleSel ? WHITE : DIM));
  if (hasRun()) {
    const v = dget(RUN_SLOT + 2);
    ctxt(`${['ALL', 'HIS', 'GEO', 'SCI', 'NAT', 'ART', 'MUS', 'SPO', 'FOO'][v & 15]} L${(v >> 4) & 15}  ${dget(RUN_SLOT + 3)}`, 222 - h + items.length * 11 + 2, ART.colors.FADED);
  }
}

const LEVEL_NOTES = ['CANDLE 6, EASY QUESTIONS', 'CANDLE 5, FAIR QUESTIONS', 'CANDLE 4, HARD QUESTIONS', 'CANDLE 3, EXPERT QUESTIONS'];
function drawSetup() {
  panel(16, 58, 224, 160);   // below the name on the title
  ctxt('A NEW GAME', 66, GOLD);
  [['SUBJECT', subject < 0 ? 'ALL SUBJECTS' : SUBJECTS[subject]], ['LEVEL', `${level} ${LEVELS[level - 1].name}`]].forEach(([k, v], i) => {
    const y = 92 + i * 30, on = i === setupRow;
    txt(k, 28, y, on ? WHITE : DIM);
    txt(on ? `< ${v} >` : `  ${v}`, 28, y + 12, on ? GOLD : WHITE);
  });
  ctxt(LEVEL_NOTES[level - 1], 160, DIM);
  if (hasRun()) ctxt('REPLACES YOUR SAVED GAME', 176, RED);
  ctxt('A: BEGIN   B: BACK', 200, DIM);
}

function drawRecords() {
  panel(24, 16, 208, 192);
  ctxt('TOP 10', 24, GOLD);
  topTen().forEach((e, i) => {
    const y = 48 + i * 14, on = i === hl;
    if (on && timer % 40 < 30) rectfill(28, y - 2, 200, 12, PANEL);
    txt(String(i + 1).padStart(2), 40, y, i === 0 ? GOLD : DIM);
    txt(e.score ? e.initials : '---', 72, y, on ? GOLD : WHITE);
    txt(e.score ? String(e.score).padStart(6) : '', 104, y, i === 0 ? GOLD : WHITE);
    if (e.score && e.level) txt(`L${e.level} ${['ALL', 'HIS', 'GEO', 'SCI', 'NAT', 'ART', 'MUS', 'SPO', 'FOO'][e.subject + 1]}`, 168, y, DIM);
  });
  if (timer % 60 < 40) ctxt('START: BACK', 192, DIM);
}

function drawInitials() {
  const ini = initials;
  panel(24, 40, 208, 144);
  ctxt(rank === 0 ? 'NEW HIGH SCORE!' : `TOP 10: #${rank + 1}`, 52, GOLD);
  ctxt(String(score), 68, WHITE);
  ctxt('ENTER YOUR INITIALS', 90, DIM);
  for (let i = 0; i < 3; i++) {
    const on = i === ini.pos, x = 84 + i * 32;
    rect(x - 2, 106, 28, 20, on ? GOLD : PANEL);
    txt(ini.chars[i], x + 10, 112, on ? GOLD : WHITE);
  }
  if (timer % 60 < 40) ctxt('START: SAVE', 160, WHITE);
}

function drawPause() {
  panel(64, 80, 128, 54);
  ctxt('PAUSED', 88, GOLD);
  PAUSE_MENU.forEach((s, i) => txt(`${i === pauseSel ? '>' : ' '} ${s}`, 76, 106 + i * 12, i === pauseSel ? WHITE : DIM));
}

/** A panel: solid, or see-through glass (`glass`) where the picture behind is dark (the title's menu, over the night). */
function panel(x, y, w, h, glass = false) { rectfill(x, y, w, h, glass ? ART.colors.GLASS : ART.colors.SHEET); rect(x, y, w, h, PANEL); }
function txt(s, x, y, c) { print(s, x + 1, y + 1, SHADOW); print(s, x, y, c); }
const ctxt = (s, y, c) => txt(s, 128 - s.length * 4, y, c);
